using System.Text;
using Guardrails.Core.Execution;
using Guardrails.Core.Model;

namespace Guardrails.Cli.Ui;

/// <summary>
/// A decorator <see cref="IRunObserver"/> that keeps the DURING-RUN live <c>diagram.html</c> up to
/// date as the run proceeds (issue #219), mirroring <see cref="OnTheFlyLogSiteObserver"/>'s exact
/// shape: it WRAPS the real observer, forwards every event verbatim, and — for the three events that
/// carry a task/check outcome — additionally flips that node's entry in an in-memory status map and
/// re-renders <c>diagram.html</c> through <see cref="Guardrails.Core.Graph.HtmlDiagramRenderer"/>.
/// </summary>
/// <remarks>
/// <para>
/// <b>Design choice (03-author-tests-diagram-observer):</b> the Mermaid source, its
/// <c>source-sha256</c>, and the task-folder-targets map are threaded in via the constructor —
/// computed by the caller through <c>Guardrails.Core.Graph.MermaidRenderer</c>, exactly as
/// <c>GraphCommand</c> already does when it first writes <c>diagram.html</c> — rather than read back
/// out of the already-written file's embedded <c>&lt;script&gt;</c> tags. The composition root
/// (<c>RunCommand</c>) already loads the <c>PlanDefinition</c> to drive the scheduler, so recomputing
/// these three pure values is cheaper and far less brittle than re-parsing HTML.
/// </para>
/// <para>
/// <b>Node-id computation.</b> A task's container id (<c>task_&lt;base&gt;</c>) and its guardrail
/// leaves' ids (<c>task_&lt;base&gt;_gr_&lt;n&gt;</c>) must match the SAME ids
/// <c>MermaidRenderer</c> already embedded in the starting <c>diagram.html</c> (written once by
/// <c>guardrails graph</c>) — otherwise the post-render overlay script could never find the SVG node
/// to badge. <c>MermaidRenderer</c>'s base-allocation algorithm is private, and this task's scope
/// forbids editing that file, so <see cref="BuildNodeIdBases"/>/<see cref="Sanitize"/> below
/// reproduce it character-for-character (ordinal-by-task-id order, first-claimant-keeps-the-base,
/// deterministic <c>_2</c>/<c>_3</c>/… suffix on collision).
/// </para>
/// <para>
/// <b>Per-check granularity.</b> Only <see cref="TaskNode.Guardrails"/> leaves are tracked — task-level
/// preflights are never reported through <see cref="GuardrailFinished"/> (<c>GuardrailRunner</c> only
/// raises it for <c>task.Guardrails</c>), so this observer only ever settles a guardrail leaf, never a
/// preflight one; <see cref="TaskStarting"/> flips the coarser task-container status only, which the
/// task instructions call out as acceptable for this deliverable.
/// </para>
/// <para>
/// <b>MINIMAL STUB (issue #219 wiring):</b> the status-map bookkeeping and event-forwarding above are
/// real. Only the actual re-render — calling <c>HtmlDiagramRenderer.Render</c> with the current status
/// snapshot and writing it to <see cref="_diagramHtmlPath"/> — throws <see cref="NotImplementedException"/>.
/// That is 04-implement-diagram-observer's job; this task's job is the failing tests that prove it.
/// </para>
/// </remarks>
public sealed class OnTheFlyDiagramObserver : IRunObserver
{
    private readonly IRunObserver _inner;
    private readonly string _diagramHtmlPath;
    private readonly string _mermaidSource;
    private readonly string _sourceHash;
    private readonly IReadOnlyDictionary<string, string> _taskFolderTargets;

    // task id -> its container node id ("task_<base>").
    private readonly IReadOnlyDictionary<string, string> _containerIdByTaskId;

    // task id -> (guardrail name -> its leaf node id "task_<base>_gr_<n>").
    private readonly IReadOnlyDictionary<string, IReadOnlyDictionary<string, string>> _guardrailLeafIdByTaskId;

    // Per-node status word, seeded "pending". Mutated and projected under one lock — events arrive
    // from concurrent M4 workers, and the render reads the whole map, so the two must not race
    // (mirrors OnTheFlyLogSiteObserver's _statusByTask).
    private readonly object _gate = new();
    private readonly Dictionary<string, string> _statusByNodeId;

    /// <param name="inner">The real observer every event is forwarded to (live or console).</param>
    /// <param name="tasks">The plan's tasks (any order) — used to allocate node ids and seed statuses.</param>
    /// <param name="diagramHtmlPath">The plan's <c>diagram.html</c> path, rewritten on every re-render.</param>
    /// <param name="mermaidSource">The exact Mermaid source already embedded by <c>guardrails graph</c>
    /// (<c>MermaidRenderer.RenderInteractive(plan)</c>) — re-passed to <c>HtmlDiagramRenderer.Render</c>
    /// on every re-render so the DAG shape never changes mid-run.</param>
    /// <param name="sourceHash">The source's <c>source-sha256</c> provenance stamp (unchanged for the run).</param>
    /// <param name="taskFolderTargets">The container-id → folder-path map (<c>MermaidRenderer.TaskFolderTargets(plan)</c>)
    /// the embedded title-band overlay script needs, re-passed through unchanged.</param>
    public OnTheFlyDiagramObserver(
        IRunObserver inner,
        IReadOnlyList<TaskNode> tasks,
        string diagramHtmlPath,
        string mermaidSource,
        string sourceHash,
        IReadOnlyDictionary<string, string> taskFolderTargets)
    {
        _inner = inner ?? throw new ArgumentNullException(nameof(inner));
        _diagramHtmlPath = diagramHtmlPath;
        _mermaidSource = mermaidSource;
        _sourceHash = sourceHash;
        _taskFolderTargets = taskFolderTargets;

        IReadOnlyDictionary<string, string> nodeIdBase = BuildNodeIdBases(tasks);

        var containerIds = new Dictionary<string, string>(StringComparer.Ordinal);
        var guardrailLeafIds = new Dictionary<string, IReadOnlyDictionary<string, string>>(StringComparer.Ordinal);
        var statuses = new Dictionary<string, string>(StringComparer.Ordinal);

        foreach (TaskNode task in tasks)
        {
            string containerId = $"task_{nodeIdBase[task.Id]}";
            containerIds[task.Id] = containerId;
            statuses[containerId] = "pending";

            var leafIds = new Dictionary<string, string>(StringComparer.Ordinal);
            int ordinal = 0;
            foreach (GuardrailDefinition guardrail in task.Guardrails.OrderBy(g => g.Name, StringComparer.Ordinal))
            {
                string leafId = $"{containerId}_gr_{ordinal}";
                leafIds[guardrail.Name] = leafId;
                statuses[leafId] = "pending";
                ordinal++;
            }

            guardrailLeafIds[task.Id] = leafIds;
        }

        _containerIdByTaskId = containerIds;
        _guardrailLeafIdByTaskId = guardrailLeafIds;
        _statusByNodeId = statuses;
    }

    public void TaskStarting(TaskNode task)
    {
        _inner.TaskStarting(task);
        if (_containerIdByTaskId.TryGetValue(task.Id, out string? containerId))
        {
            SetStatus(containerId, "running");
        }

        RenderDiagram();
    }

    public void AttemptStarting(TaskNode task, int attempt, int budget) =>
        _inner.AttemptStarting(task, attempt, budget);

    public void GuardrailFinished(TaskNode task, GuardrailResult result)
    {
        _inner.GuardrailFinished(task, result);
        if (_guardrailLeafIdByTaskId.TryGetValue(task.Id, out IReadOnlyDictionary<string, string>? leafIds) &&
            leafIds.TryGetValue(result.Name, out string? leafId))
        {
            SetStatus(leafId, result.Passed ? "passed" : "failed");
        }

        RenderDiagram();
    }

    public void TaskFinished(TaskResult result)
    {
        _inner.TaskFinished(result);
        if (_containerIdByTaskId.TryGetValue(result.TaskId, out string? containerId))
        {
            SetStatus(containerId, StatusWord(result.Outcome));
        }

        RenderDiagram();
    }

    public void PlanHashMismatch(string previousPlanHash) => _inner.PlanHashMismatch(previousPlanHash);

    public void ParallelismClampedNoProvider(int requested) => _inner.ParallelismClampedNoProvider(requested);

    public void CleanupFailed(string owner, Exception error) => _inner.CleanupFailed(owner, error);

    public void PromptPaused(TaskNode task, string reason, TimeSpan backoff, int pauseCount) =>
        _inner.PromptPaused(task, reason, backoff, pauseCount);

    // --- diagram projection -------------------------------------------------------------------

    private void SetStatus(string nodeId, string status)
    {
        lock (_gate)
        {
            _statusByNodeId[nodeId] = status;
        }
    }

    /// <summary>
    /// Rewrite <c>diagram.html</c> from the current status map. Holds the lock for the whole render
    /// so the status snapshot is internally consistent (mirrors <c>OnTheFlyLogSiteObserver.RenderIndex</c>).
    /// Best-effort: a render failure is swallowed (see <see cref="TryRender"/>) so this UX nicety never
    /// flips a task's outcome or aborts the run.
    /// </summary>
    private void RenderDiagram()
    {
        lock (_gate)
        {
