    /// Rewrite <c>diagram.html</c> from the current status map. Holds the lock for the whole render
    /// so the status snapshot is internally consistent (mirrors <c>OnTheFlyLogSiteObserver.RenderIndex</c>).
    /// Best-effort: a render failure is swallowed (see <see cref="TryRender"/>) so this UX nicety never
    /// flips a task's outcome or aborts the run.
    /// </summary>
    private void RenderDiagram()
    {
        lock (_gate)
        {
            var statuses = new Dictionary<string, string>(_statusByNodeId, StringComparer.Ordinal);
            TryRender(() => WriteDiagram(statuses));
        }
    }

    /// <summary>
    /// MINIMAL STUB (issue #219 wiring): the real re-render — calling
    /// <c>HtmlDiagramRenderer.Render(_mermaidSource, _sourceHash, _taskFolderTargets, statuses, ...)</c>
    /// and writing the result to <see cref="_diagramHtmlPath"/> — is 04-implement-diagram-observer's
    /// job. This task's job is the failing tests that prove the status-map bookkeeping above is right.
    /// </summary>
    private void WriteDiagram(IReadOnlyDictionary<string, string> statuses) =>
        throw new NotImplementedException();

    /// <summary>Map a finished task's outcome to the diagram overlay's settled status word.</summary>
    private static string StatusWord(TaskOutcome outcome) => outcome switch
    {
        // Succeeded this run, or already-succeeded per a resumed journal (SSOT §7's IsGreen).
        TaskOutcome.Succeeded or TaskOutcome.Skipped => "passed",
        // Both are "re-run later", not a task defect to debug (see TaskOutcome's own remarks).
        TaskOutcome.NeedsHuman or TaskOutcome.RateLimited => "needs-human",
        // ActionFailed / GuardrailFailed / InvalidFragment / Blocked / Cancelled all settled non-green.
        _ => "failed",
    };

    /// <summary>
    /// Run a render action, swallowing IO failures: the live diagram is a UX nicety and must never
    /// flip a task's outcome or abort the run (mirrors <c>OnTheFlyLogSiteObserver.TryRender</c>).
    /// </summary>
    private static void TryRender(Action render)
    {
        try
        {
            render();
        }
        catch (IOException)
        {
            // best-effort — the next event re-renders
        }
        catch (UnauthorizedAccessException)
        {
            // best-effort — never let a diagram-path permission hiccup abort the run
        }
    }

    // --- node id helpers ------------------------------------------------------------------------
    // Reproduces Guardrails.Core.Graph.MermaidRenderer's private AllocateNodeIdBases/Sanitize
    // algorithm character-for-character (see remarks) so container ids computed here exactly match
    // the ids already embedded in the starting diagram.html.

    private static IReadOnlyDictionary<string, string> BuildNodeIdBases(IReadOnlyList<TaskNode> tasks)
    {
        List<TaskNode> ordered = tasks.OrderBy(t => t.Id, StringComparer.Ordinal).ToList();
        var bases = new Dictionary<string, string>(StringComparer.Ordinal);
        var taken = new HashSet<string>(StringComparer.Ordinal);

        foreach (TaskNode task in ordered)
        {
            string candidate = Sanitize(task.Id);
            if (!taken.Add(candidate))
            {
                int suffix = 2;
                string disambiguated;
                do
                {
                    disambiguated = $"{candidate}_{suffix}";
                    suffix++;
                }
                while (!taken.Add(disambiguated));

                candidate = disambiguated;
            }

            bases[task.Id] = candidate;
        }

        return bases;
    }

    private static string Sanitize(string id)
    {
        var sb = new StringBuilder(id.Length);
        foreach (char c in id)
        {
            bool safe = c is (>= 'a' and <= 'z') or (>= 'A' and <= 'Z') or (>= '0' and <= '9');
            sb.Append(safe ? c : '_');
        }

        return sb.ToString();
    }
}

