using System.Text.Json;
using Guardrails.Cli.Ui;
using Guardrails.Core.Execution;
using Guardrails.Core.Graph;
using Guardrails.Core.Model;

namespace Guardrails.Integration.Tests;

/// <summary>
/// Exercises the on-the-fly live-diagram decorator (<see cref="OnTheFlyDiagramObserver"/>, issue
/// #219): as tasks/guardrails settle it flips the matching node's entry in an in-memory status map
/// and re-renders <c>diagram.html</c>, and forwards EVERY event to the inner observer. Driven directly
/// against the decorator (no real Scheduler) — mirrors <c>OnTheFlyLogSiteTests</c>' pattern of hand-
/// firing events and reading the rendered artifact back off disk.
/// <para>
/// <b>RED against the throwing stub (03-author-tests-diagram-observer):</b> the decorator's own
/// status-map bookkeeping is real, but the actual re-render throws <see cref="NotImplementedException"/>
/// (see the class remarks on <see cref="OnTheFlyDiagramObserver"/>), so every test below that fires an
/// event and then reads <c>diagram.html</c> back fails with that exception today — the TDD red
/// 04-implement-diagram-observer turns green. The pure pass-through test does not touch the render
/// path at all, so it already passes.
/// </para>
/// </summary>
public sealed class OnTheFlyDiagramObserverTests
{
    [Fact]
    public void TaskStarting_RerendersDiagramWithTheTaskMarkedRunning()
    {
        using var temp = new TempPlan();
        TaskNode task = temp.Task("01-first", "01-build");
        OnTheFlyDiagramObserver observer = temp.CreateObserver(IRunObserver.Null, [task]);

        observer.TaskStarting(task);

        IReadOnlyDictionary<string, string> statuses = ReadNodeStatuses(temp.ReadDiagram());
        Assert.Equal("running", statuses.GetValueOrDefault("task_01_first"));
    }

    [Fact]
    public void GuardrailFinished_RerendersDiagramWithThatChecksSettledStatus()
    {
        using var temp = new TempPlan();
        TaskNode task = temp.Task("01-first", "01-a", "02-b");
        OnTheFlyDiagramObserver observer = temp.CreateObserver(IRunObserver.Null, [task]);

        observer.GuardrailFinished(task, new GuardrailResult { Name = "01-a", Passed = true });
        observer.GuardrailFinished(task, new GuardrailResult { Name = "02-b", Passed = false, Reason = "boom" });

        IReadOnlyDictionary<string, string> statuses = ReadNodeStatuses(temp.ReadDiagram());

        // Ordinal 0/1 come from sorting task.Guardrails by name ("01-a" before "02-b").
        Assert.Equal("passed", statuses.GetValueOrDefault("task_01_first_gr_0"));
        Assert.Equal("failed", statuses.GetValueOrDefault("task_01_first_gr_1"));

        // A single check's result must settle only that check's leaf id, never the whole task.
        Assert.Equal("pending", statuses.GetValueOrDefault("task_01_first"));
    }

    [Theory]
    [InlineData(TaskOutcome.Succeeded, "passed")]
    [InlineData(TaskOutcome.Skipped, "passed")]
    [InlineData(TaskOutcome.GuardrailFailed, "failed")]
    [InlineData(TaskOutcome.Blocked, "failed")]
    [InlineData(TaskOutcome.NeedsHuman, "needs-human")]
    [InlineData(TaskOutcome.RateLimited, "needs-human")]
    public void TaskFinished_RerendersDiagramWithTheTasksSettledStatus(TaskOutcome outcome, string expectedStatus)
    {
        using var temp = new TempPlan();
        TaskNode task = temp.Task("01-first", "01-a");
        OnTheFlyDiagramObserver observer = temp.CreateObserver(IRunObserver.Null, [task]);

        observer.TaskFinished(new TaskResult { TaskId = "01-first", Outcome = outcome, Summary = "x" });

        IReadOnlyDictionary<string, string> statuses = ReadNodeStatuses(temp.ReadDiagram());
        Assert.Equal(expectedStatus, statuses.GetValueOrDefault("task_01_first"));
    }

    [Fact]
    public void EveryOtherObserverEvent_IsForwardedToInner_Unchanged()
    {
        using var temp = new TempPlan();
        TaskNode task = temp.Task("01-first", "01-a");
        var inner = new RecordingObserver();
        OnTheFlyDiagramObserver observer = temp.CreateObserver(inner, [task]);

        observer.AttemptStarting(task, 2, 3);
        observer.PlanHashMismatch("sha256:old");
        observer.ParallelismClampedNoProvider(4);
        observer.CleanupFailed("01-first", new InvalidOperationException("cleanup boom"));
        observer.PromptPaused(task, "rate limited", TimeSpan.FromSeconds(30), 1);

        Assert.Equal(
            new[]
            {
                "AttemptStarting:01-first:2:3",
                "PlanHashMismatch:sha256:old",
                "ParallelismClampedNoProvider:4",
                "CleanupFailed:01-first:cleanup boom",
                "PromptPaused:01-first:rate limited:30:1",
            },
            inner.Events);
    }

    [Fact]
    public void ARenderFailure_IsSwallowed_AndDoesNotThrow()
    {
        using var temp = new TempPlan();
        TaskNode task = temp.Task("01-first", "01-a");

        // An invalid output path (a directory, not a writable file) makes any real write throw
        // IOException/UnauthorizedAccessException — TryRender must swallow it so a UX nicety never
        // aborts the run (mirrors OnTheFlyLogSiteObserver's documented best-effort behavior).
        var observer = new OnTheFlyDiagramObserver(
            IRunObserver.Null,
            [task],
            diagramHtmlPath: temp.Dir,
            mermaidSource: "flowchart TD\n",
            sourceHash: "deadbeef",
            taskFolderTargets: new Dictionary<string, string>(StringComparer.Ordinal));

        Exception? thrown = Record.Exception(() => observer.TaskStarting(task));

        Assert.Null(thrown);
    }

    /// <summary>Extract the <c>#node-statuses</c> JSON side-table HtmlDiagramRenderer embeds.</summary>
    private static IReadOnlyDictionary<string, string> ReadNodeStatuses(string html)
    {
        const string marker = "<script type=\"application/json\" id=\"node-statuses\">";
        int start = html.IndexOf(marker, StringComparison.Ordinal);
        Assert.True(start >= 0, "diagram.html has no #node-statuses side-table");

        start += marker.Length;
        int end = html.IndexOf("</script>", start, StringComparison.Ordinal);
        Assert.True(end >= 0, "malformed #node-statuses script tag in diagram.html");

        string json = html[start..end];
        return JsonSerializer.Deserialize<Dictionary<string, string>>(json) ?? new Dictionary<string, string>();
    }

    /// <summary>Records the identity/order/arguments of every forwarded event so the decorator's pass-through is provable.</summary>
    private sealed class RecordingObserver : IRunObserver
    {
        public List<string> Events { get; } = [];

        public void TaskStarting(TaskNode task) => Events.Add($"TaskStarting:{task.Id}");
        public void TaskFinished(TaskResult result) => Events.Add($"TaskFinished:{result.TaskId}");
        public void GuardrailFinished(TaskNode task, GuardrailResult result) => Events.Add($"GuardrailFinished:{task.Id}");

        public void AttemptStarting(TaskNode task, int attempt, int budget) =>
            Events.Add($"AttemptStarting:{task.Id}:{attempt}:{budget}");

        public void PlanHashMismatch(string previousPlanHash) =>
            Events.Add($"PlanHashMismatch:{previousPlanHash}");

        public void ParallelismClampedNoProvider(int requested) =>
            Events.Add($"ParallelismClampedNoProvider:{requested}");

        public void CleanupFailed(string owner, Exception error) =>
            Events.Add($"CleanupFailed:{owner}:{error.Message}");

        public void PromptPaused(TaskNode task, string reason, TimeSpan backoff, int pauseCount) =>
            Events.Add($"PromptPaused:{task.Id}:{reason}:{(int)backoff.TotalSeconds}:{pauseCount}");
    }

    /// <summary>
    /// A throwaway plan directory whose <c>diagram.html</c> starts as the plain static <c>graph</c>
    /// render (no live status) — the same starting state a real plan carries before it is ever run.
    /// </summary>
    private sealed class TempPlan : IDisposable
    {
        private const string Hash = "deadbeef";
        private const string Source = "flowchart TD\n  task_01_first[\"01-first\"]:::task\n";

        public string Dir { get; } = Path.Combine(Path.GetTempPath(), "gr-otf-diagram-" + Guid.NewGuid().ToString("N"));

        public string DiagramHtmlPath => Path.Combine(Dir, "diagram.html");

        public TempPlan() => Directory.CreateDirectory(Dir);

        public TaskNode Task(string id, params string[] guardrailNames) => new()
        {
            Id = id,
            Directory = Path.Combine(Dir, "tasks", id),
            Description = "task " + id,
            Action = new ActionDefinition { Path = "action.ps1", Kind = ActionKind.Script },
            Guardrails = guardrailNames
                .Select(n => new GuardrailDefinition { Name = n, Path = n + ".ps1", Kind = ActionKind.Script })
                .ToArray(),
        };

        public OnTheFlyDiagramObserver CreateObserver(IRunObserver inner, IReadOnlyList<TaskNode> tasks)
        {
            var targets = new Dictionary<string, string>(StringComparer.Ordinal);
            File.WriteAllText(DiagramHtmlPath, HtmlDiagramRenderer.Render(Source, Hash, targets));
            return new OnTheFlyDiagramObserver(inner, tasks, DiagramHtmlPath, Source, Hash, targets);
        }

        public string ReadDiagram() => File.ReadAllText(DiagramHtmlPath);

        public void Dispose()
        {
            try { Directory.Delete(Dir, recursive: true); } catch (Exception) { /* best effort */ }
        }
    }
}

